int max = 0;
string bester = "";
using (StreamReader r =
       new StreamReader("p.csv"))
{
    while (!r.EndOfStream)
    {
        string[] t = r.ReadLine().Split(';');
        int p = int.Parse(t[1]);
        if (p > max)
        {
            max = p;
            bester = t[0];
        }
    }
}
Console.WriteLine($"{bester} {max}");

